from glossar_data import E
G1 = "Depressive & bipolare Störungen"
G2 = "Angststörungen"
G3 = "Zwang & verwandte Störungen"
LISTE = [
E("Depressive Episode / Major Depression", G1, "F32.x (einzeln), F33.x (rezidivierend)", "6A70 (einzelne Episode), 6A71 (rezidivierend)", "Major Depressive Disorder, F32.x / F33.x",
  "Mindestens zwei Wochen anhaltend gedrückte Stimmung, Interessen-/Freudverlust und Antriebsminderung mit deutlicher Beeinträchtigung; Schweregrad leicht, mittel, schwer (mit/ohne psychotische Symptome).",
  ["Gedrückte Stimmung, Leere, Hoffnungslosigkeit", "Interessen- und Freudverlust (Anhedonie)", "Antriebsmangel, rasche Erschöpfbarkeit", "Schlafstörungen (Früherwachen), Appetit-/Gewichtsveränderung", "Konzentrations- und Entscheidungsprobleme", "Schuldgefühle, Wertlosigkeit, Grübeln", "Psychomotorische Hemmung oder Unruhe", "Suizidgedanken bis -handlungen (immer explorieren)"],
  "Biopsychosoziales Vulnerabilitäts-Stress-Modell: genetische Disposition, Veränderungen von Serotonin-/Noradrenalin-/Stresshormonsystem (HPA-Achse), frühe Belastungen, negative kognitive Schemata (Beck), Verstärkerverlust (Lewinsohn), erlernte Hilflosigkeit (Seligman), kritische Lebensereignisse, Verlust, chronischer Stress, soziale Isolation.",
  "Ein Zusammenspiel aus Veranlagung, Belastungen und Lebensumständen. Wenn Stress, Verluste oder Überforderung lange anhalten, gerät der Körper-Stoffwechsel und das Denken in eine Abwärtsspirale: weniger Aktivität, weniger Freude, mehr negative Gedanken.",
  "Depression ist eine ernsthafte, gut behandelbare Erkrankung – kein Zeichen von Schwäche und keine Charakterfrage. Sie verändert Stimmung, Antrieb, Schlaf und Denken. Mit Therapie, Aktivierung und bei Bedarf Medikamenten bessert sie sich bei den allermeisten Menschen deutlich.",
  "Verhaltensaktivierung (Aufbau angenehmer/sinnvoller Aktivitäten), kognitive Umstrukturierung negativer Gedanken, Problemlösetraining, Grübeln bearbeiten (Metakognition), Rückfallprophylaxe; bei Chronifizierung CBASP; MBCT zur Rückfallprophylaxe.",
  "Erarbeiten unbewusster Konflikte (z. B. Selbstwert, Abhängigkeit, Aggressionshemmung), Verlust- und Kränkungserfahrungen, Beziehungsmuster in der Übertragung; Fokus auf aktuellen Auslöser und lebensgeschichtliche Wurzeln.",
  "Depression im Beziehungskontext verstehen: Funktion des Symptoms im System, Rollen, Erwartungen, Ressourcen und Ausnahmen; Einbezug von Partner/Familie, Zirkuläre Fragen, Ressourcenaktivierung.",
  "Gesprächspsychotherapie: bedingungsfreie Wertschätzung und Empathie fördern Selbstakzeptanz; emotionsfokussiert: Zugang zu Schmerz, Scham und unerfülltem Bedürfnis und deren Transformation.",
  "S3-Leitlinie Unipolare Depression: Psychotherapie (VT, TP, IPT) bei leichter bis mittelgradiger Depression gleichwertig zu Medikation; bei schwerer Depression Kombination. Antidepressiva ärztlich verordnen. Suizidalität stets abklären."),
E("Persistierende depressive Störung (Dysthymie)", G1, "F34.1", "6A72", "Persistent Depressive Disorder, F34.1",
  "Chronisch gedrückte Stimmung an den meisten Tagen über mindestens zwei Jahre (bei Jugendlichen ein Jahr), meist mit geringerer Intensität als bei einer Major Depression.",
  ["Anhaltende Niedergeschlagenheit über Jahre", "Geringes Selbstwertgefühl, Pessimismus", "Müdigkeit, wenig Energie", "Schlaf- und Appetitveränderungen", "Konzentrationsschwierigkeiten", "Gefühl, 'schon immer so gewesen zu sein'", "Häufig aufgesetzte depressive Episoden (\"double depression\")"],
  "Frühe Beziehungs- und Bindungsbelastungen, chronische Überforderung, dysfunktionale Grundüberzeugungen, genetische Disposition, früher Beginn (oft vor dem 21. Lebensjahr).",
  "Oft beginnt es früh im Leben. Man gewöhnt sich an das Grau und hält es für 'die eigene Persönlichkeit'.",
  "Es ist eine echte, behandelbare Erkrankung – kein Charakterzug. Auch wenn es schon lange besteht, kann sich das Erleben deutlich verändern.",
  "CBASP (Cognitive Behavioral Analysis System of Psychotherapy) als Verfahren der Wahl bei Chronifizierung, Verhaltensaktivierung, Selbstwertaufbau, Modifikation von Grundannahmen.",
  "Bearbeitung früher Beziehungserfahrungen, Selbstwertregulation, innere Konflikte, Idealisierungs- und Entwertungsmuster; längere Therapiedauer.",
  "Wie stabilisiert das Symptom das System? Rollen und Aufträge in der Herkunftsfamilie, Ressourcen, Zukunftsentwürfe, Unterschiede, die einen Unterschied machen.",
  "Wertschätzende Beziehung als korrigierende Erfahrung; Zugang zu verdrängten Gefühlen und Bedürfnissen.",
  "Oft Langzeitverlauf; Kombination aus Psychotherapie und ggf. Medikation. Suizidrisiko abklären."),
E("Bipolare Störungen (Bipolar I / II)", G1, "F31.x", "6A60 (Bipolar I), 6A61 (Bipolar II)", "Bipolar I / II Disorder, F31.x",
  "Episodischer Wechsel zwischen depressiven und (hypo-)manischen Phasen. Bipolar I: mindestens eine manische Episode; Bipolar II: Hypomanie plus Depression.",
  ["Manie: gehobene/gereizte Stimmung, vermindertes Schlafbedürfnis, Rededrang, Ideenflucht", "Größenideen, Selbstüberschätzung, Risikoverhalten (Geld, Sexualität)", "Hypomanie: weniger ausgeprägt, ohne massive Funktionsstörung", "Depressive Phasen wie bei Major Depression", "Mischzustände möglich", "Hohes Suizidrisiko, besonders in depressiven und gemischten Phasen"],
  "Hohe Erblichkeit, Störungen der zirkadianen Rhythmik und Neurotransmission, Auslöser: Stress, Schlafmangel, Substanzen, Jahreszeit; psychosoziale Faktoren beeinflussen den Verlauf.",
  "Stark erblich beeinflusst. Unregelmäßiger Schlaf, Stress oder Drogen können Episoden auslösen.",
  "Die Stimmung schwankt stärker als bei normalen Hoch- und Tiefpunkten, über Tage bis Wochen. Mit stabilen Alltagsroutinen, Frühwarnzeichen-Plan und passender Medikation lassen sich Rückfälle deutlich verringern.",
  "Psychoedukation, Frühwarnzeichen und Krisenplan, Stimmungstagebuch, Schlaf-/Tagesrhythmus (interpersonelle und soziale Rhythmustherapie IPSRT), Behandlung der Depression, Rückfallprophylaxe.",
  "Verständnis der Bedeutung der Episoden für Selbstwert und Beziehungen, Umgang mit Kontrollverlust und Idealisierung; ergänzend, nicht ersetzend zur Pharmakotherapie.",
  "Angehörige einbeziehen (familienfokussierte Therapie), Kommunikation in Krisen, gemeinsame Vereinbarungen.",
  "Stützende, stabilisierende Beziehung; Akzeptanz der Erkrankung; Förderung von Selbstfürsorge.",
  "S3-Leitlinie Bipolare Störungen: Phasenprophylaxe (z. B. Lithium) ärztlich; Psychotherapie als Ergänzung. In Manie keine Aufdeckung."),
E("Zyklothymie", G1, "F34.0", "6A62", "Cyclothymic Disorder, F34.0",
  "Über mindestens zwei Jahre wiederkehrende hypomanische und depressive Schwankungen, die die Kriterien für Hypomanie bzw. Depression nicht voll erfüllen.",
  ["Wechsel zwischen leicht gehobener und gedrückter Stimmung", "Wechselhafte Energie und Aktivität", "Unbeständigkeit in Beziehungen und Beruf", "Reizbarkeit"],
  "Genetische Nähe zum bipolaren Spektrum, Temperament, Stress- und Schlafrhythmusstörungen.",
  "Eine angeborene Stimmungsempfindlichkeit, die durch Stress verstärkt wird.",
  "Ihre Stimmung schwankt ungewöhnlich stark, ohne dass es eine schwere Krise ist. Das ist gut behandelbar.",
  "Stimmungs- und Aktivitätsmonitoring, Strukturierung des Tagesablaufs, Schlafhygiene, Emotionsregulation.",
  "Verständnis der inneren Dynamik von Idealisierung und Abwertung, Selbstwertregulation.",
  "Muster in Beziehungen und Arbeit, stabilisierende Routinen im Umfeld.",
  "Selbstakzeptanz und Gefühlsdifferenzierung.",
  "Abgrenzung zu Borderline und Bipolar II beachten."),
E("Postpartale / peripartale Depression", G1, "F53.0 (leichte Störungen im Wochenbett), F32.x/F33.x mit Zusatz", "6E20", "Major Depressive Disorder with peripartum onset, F32.x",
  "Depressive Episode während der Schwangerschaft oder bis zu mehreren Monaten nach der Geburt; abzugrenzen vom 'Baby-Blues' (kurz, mild) und der postpartalen Psychose (Notfall).",
  ["Anhaltende Traurigkeit, Weinen", "Erschöpfung trotz Schlafmöglichkeit", "Schuld- und Versagensgefühle als Mutter/Vater", "Angst um das Kind oder Gleichgültigkeit", "Zwangsgedanken (Kind schaden) ohne Handlungsabsicht", "Rückzug, Reizbarkeit", "Suizidgedanken"],
  "Hormonelle Umstellung, Schlafentzug, Belastung durch Rollenwechsel, frühere Depressionen, fehlende Unterstützung, Geburtserleben, Partnerschaftskonflikte.",
  "Hormone, Schlafmangel und die große Umstellung treffen zusammen – oft auf schon vorhandene Belastungen.",
  "Das kommt häufig vor und hat nichts damit zu tun, dass Sie ein schlechter Elternteil sind. Es ist behandelbar, und frühe Hilfe schützt auch das Kind.",
  "Verhaltensaktivierung, Entlastung und Schlafschutz, Umgang mit Schuld und Perfektionismus, Elternkompetenz, Kooperation mit Hebamme/Facharzt.",
  "Mutter-/Vaterrolle, eigene Bindungserfahrungen, Ambivalenz gegenüber dem Kind; interpersonelle Therapie (IPT) wirksam.",
  "Einbezug des Partners/Familie, Neuverteilung von Aufgaben und Rollen, soziale Netzwerke.",
  "Entlastendes Gespräch, Schuld- und Schamgefühle annehmen.",
  "Bei psychotischen Symptomen oder akuter Gefährdung sofort ärztlich/stationär. Zwangsgedanken sind meist harmlos (ego-dyston), aber ansprechen."),
E("Panikstörung", G2, "F41.0", "6B01", "Panic Disorder, F41.0",
  "Wiederkehrende, unerwartete Panikattacken mit anhaltender Sorge vor weiteren Attacken oder deren Folgen und/oder Vermeidungsverhalten.",
  ["Plötzliche Angstwelle mit Herzrasen, Atemnot, Schwindel, Zittern, Schwitzen", "Todesangst, Angst durchzudrehen oder die Kontrolle zu verlieren", "Derealisation/Depersonalisation", "Erwartungsangst vor der nächsten Attacke", "Vermeiden von Orten und Aktivitäten (oft Agoraphobie)", "Ständiges Körperabtasten, Notaufnahmebesuche"],
  "Vulnerabilität (genetisch, Angstsensitivität), körperliche Empfindungen werden katastrophisierend gedeutet (Clark: Teufelskreis), konditionierte Angst auf interozeptive Reize, Stress, Koffein/Substanzen.",
  "Der Körper reagiert normal auf Stress (Herz schlägt schneller). Wird das als Gefahr bewertet, steigt die Angst weiter – und der Kreislauf schaukelt sich auf.",
  "Eine Panikattacke fühlt sich lebensbedrohlich an, ist aber körperlich ungefährlich und vergeht nach Minuten. Das Wissen darüber und gezielte Übungen führen meist zu deutlicher Besserung.",
  "Psychoedukation (Teufelskreis), Interozeptive Exposition (Körperübungen), Konfrontation in vivo, Sicherheitsverhalten abbauen, kognitive Umstrukturierung von Katastrophengedanken.",
  "Angst als Ausdruck unbewusster Konflikte (Trennung vs. Autonomie, Aggression), Umgang mit Abhängigkeits-Autonomie-Thema; psychodynamische Panikfokussierte Therapie (PFPP) belegt.",
  "Funktion der Angst im Beziehungsgefüge (z. B. Schonung/Nähe), Aufträge, Umgang der Angehörigen mit der Angst.",
  "Akzeptanz der Angst, Erleben und Verstehen von Gefühlen, Förderung von Selbstvertrauen.",
  "S3-Leitlinie Angststörungen: KVT (Exposition) erste Wahl; SSRI/SNRI ärztlich möglich, Benzodiazepine vermeiden. Körperliche Abklärung (Herz, Schilddrüse)."),
E("Agoraphobie", G2, "F40.0 (mit/ohne Panikstörung F40.00 / F40.01)", "6B02", "Agoraphobia, F40.00",
  "Ausgeprägte Angst vor oder Vermeidung von Situationen, aus denen Flucht schwierig oder Hilfe nicht verfügbar wäre (Menschenmengen, öffentliche Verkehrsmittel, Weite, Alleinsein außer Haus).",
  ["Angst in Menschenmengen, Warteschlangen, Kaufhäusern", "Angst vor Bus, Bahn, Brücken, weiten Plätzen", "Angst, allein das Haus zu verlassen", "Vermeidung oder Begleitung nur mit Vertrauensperson", "Antizipatorische Angst, oft Panikattacken"],
  "Konditionierung (Lernen durch Erfahrung und Vermeidung), Panikattacken als Auslöser, Lernen am Modell, genetische Faktoren; Vermeidung hält die Angst aufrecht (negative Verstärkung).",
  "Nach einer Panik- oder Angsterfahrung meidet man Orte. Das gibt kurz Erleichterung, aber die Angst wird größer und der Radius kleiner.",
  "Die Angst vor 'Orten ohne Ausweg' ist verständlich, und sie lässt sich schrittweise verlernen.",
  "Graduierte Expositionshierarchie (in vivo), Abbau von Sicherheitsverhalten, Rückfallprophylaxe.",
  "Autonomie-Abhängigkeits-Konflikte, Trennungsthemen, Funktion der Begleitung.",
  "Rolle der begleitenden Person, Muster von Schutz und Kontrolle, Ressourcen für Selbständigkeit.",
  "Gefühle hinter der Angst erkunden; Selbstwirksamkeit stärken.",
  "S3-Leitlinie: KVT mit Exposition erste Wahl."),
E("Soziale Angststörung (Soziale Phobie)", G2, "F40.1", "6B04", "Social Anxiety Disorder, F40.10",
  "Ausgeprägte, anhaltende Angst vor sozialen Situationen, in denen man bewertet werden könnte, aus Furcht, sich peinlich zu verhalten oder negativ beurteilt zu werden.",
  ["Angst vor Reden, Essen, Schreiben vor anderen, Blickkontakt", "Erröten, Zittern, Schwitzen, Stimmversagen", "Gedanken: 'Ich blamiere mich'", "Vermeiden von Treffen, Präsentationen, Telefonaten", "Starke Selbstbeobachtung", "Nachgrübeln nach sozialen Situationen (Post-Event-Processing)"],
  "Kognitives Modell (Clark & Wells): negative Selbstbilder, Selbstfokussierung, Sicherheitsverhalten; Temperament (Verhaltenshemmung), kritische/überbehütende Erziehung, Mobbing- und Beschämungserfahrungen.",
  "Wer früh Beschämung erlebt hat, achtet später sehr auf Wirkung. Der Blick nach innen und das Vermeiden verhindern, dass man Gegenteiliges erlebt.",
  "Sie sind nicht 'einfach schüchtern': Es ist eine erlernte Angst, die sich mit Übung verändert.",
  "Kognitive Therapie nach Clark & Wells (Aufmerksamkeitsumlenkung, Videofeedback, Verhaltensexperimente), Exposition, Abbau von Sicherheitsverhalten.",
  "Scham, Selbstwert, Konflikt um Auffallen und Zugehörigkeit; Beziehungsmuster mit Beschämung.",
  "Muster von Bewertung und Zugehörigkeit in Familie/Gruppen, Kontext-Veränderungen, Ressourcen.",
  "Selbstmitgefühl, Zugang zu Scham, Authentizität im Gegenüber.",
  "S3-Leitlinie: KVT erste Wahl; SSRI möglich ärztlich."),
E("Spezifische Phobie", G2, "F40.2", "6B03", "Specific Phobia, F40.2xx",
  "Übermäßige, situations- oder objektbezogene Angst (Tiere, Höhe, Spritzen/Blut, Fliegen, Enge u. a.) mit Vermeidung und deutlichem Leidensdruck.",
  ["Unmittelbare Angst bei Konfrontation oder Vorstellung", "Vermeidung oder Ertragen unter starker Angst", "Einsicht in Übertreibung, aber Kontrollverlust", "Bei Blut-Spritzen-Verletzung: Kreislaufabfall/Ohnmacht"],
  "Klassische und operante Konditionierung, Modelllernen, Informationsvermittlung, evolutionäre Prädisposition (Vorbereitetheit).",
  "Angst vor bestimmten Dingen wird durch Erfahrung, Beobachtung oder Erzählungen gelernt und durch Vermeiden gefestigt.",
  "Das ist eine der am besten behandelbaren psychischen Störungen – oft genügen wenige Sitzungen.",
  "Exposition in vivo (auch einmalige Intensivsitzung ~3 Stunden), bei Blutphobie angespannte Muskeln (Applied Tension), Virtual Reality.",
  "Symbolische Bedeutung des Objekts selten nötig, ggf. bei Chronifizierung.",
  "Rolle im System, Entlastung von Angehörigen.",
  "Akzeptanz, Begleitung bei schrittweiser Annäherung.",
  "Exposition erste Wahl."),
E("Generalisierte Angststörung", G2, "F41.1", "6B00", "Generalized Anxiety Disorder, F41.1",
  "Anhaltende, schwer kontrollierbare Sorgen über viele Lebensbereiche (Gesundheit, Familie, Arbeit, Geld) an den meisten Tagen über mindestens sechs Monate mit körperlicher Anspannung.",
  ["Ständiges Sorgen, 'Was wäre wenn?'", "Innere Unruhe, Anspannung", "Konzentrationsprobleme", "Schlafstörungen, Reizbarkeit", "Muskelverspannungen", "Rückversicherungsverhalten, Aufschieben"],
  "Intoleranz von Unsicherheit (Dugas), Sorgen als kognitive Vermeidung, positive Überzeugungen über Sorgen (Metakognition, Wells), Bindungs- und Stresserfahrungen, genetische Faktoren.",
  "Sorgen wirken wie ein Schutz, halten aber den Körper dauerhaft in Alarmbereitschaft. Die Unsicherheit ist schwer auszuhalten.",
  "Sorgen sind zunächst normal, werden hier aber zur Dauerschleife. Sie lernen, besser mit Unsicherheit umzugehen und die Sorgen loszulassen.",
  "Sorgenexposition, Sorgenzeit, Metakognitive Therapie, Training der Unsicherheitstoleranz, Entspannung (Progressive Muskelrelaxation), Achtsamkeit/ACT.",
  "Hintergrund von Überverantwortung, Kontrolle und Trennungsängsten; Beziehungserfahrungen mit Unsicherheit.",
  "Funktion der Sorge in der Familie (Fürsorge/Kontrolle), Erwartungen, Rollenverteilungen.",
  "Gefühle hinter den Sorgen, Zugang zu Bedürfnissen.",
  "S3-Leitlinie: KVT erste Wahl; Medikation (SSRI/SNRI, Pregabalin) ärztlich."),
E("Zwangsstörung", G3, "F42.x", "6B20", "Obsessive-Compulsive Disorder, F42.2",
  "Wiederkehrende aufdrängende Gedanken, Impulse oder Bilder (Zwangsgedanken) und/oder Zwangshandlungen, die Angst oder Anspannung neutralisieren sollen, zeitaufwendig (>1 Std./Tag) oder beeinträchtigend.",
  ["Zwangsgedanken: Kontamination, Aggression, Sexualität, Symmetrie, Religion", "Zwangshandlungen: Waschen, Kontrollieren, Zählen, Ordnen", "Gedankliche Rituale und Rückversicherung", "Einsicht oft vorhanden, aber Handlungsdrang", "Vermeidung von Auslösern", "Hoher Zeitaufwand, Scham"],
  "Neurobiologisch (kortiko-striato-thalamische Schleifen), Lernmodell (Mowrer: Angst – Ritual – kurzfristige Erleichterung), dysfunktionale Annahmen (Überverantwortung, Gedanken-Handlungs-Fusion, Perfektionismus), genetische Faktoren, Stress.",
  "Ein Gehirn, das Gefahr überbewertet, plus der Versuch, die Angst mit Ritualen zu beruhigen. Das Ritual hilft kurz, hält das Problem aber am Leben.",
  "Aufdrängende Gedanken haben viele Menschen. Sie sagen nichts über Ihren Charakter oder Ihre Absichten. Mit der richtigen Methode (nicht ausweichen, Rituale weglassen) bessern sie sich meist deutlich.",
  "Exposition mit Reaktionsmanagement (ERP) als Mittel der Wahl, kognitive Bearbeitung von Verantwortungsannahmen, Angehörige einbeziehen.",
  "Kontrolle und Aggression, Ambivalenz, Reinheit und Schuld; ergänzend bei Persönlichkeitsanteilen.",
  "Rolle des Zwangs in der Familie (Akkommodation), Kontrolle und Nähe, Entlastung der Angehörigen.",
  "Wertschätzende Begegnung, Entlastung von Scham; als Ergänzung.",
  "S3-Leitlinie Zwangsstörungen: KVT mit ERP erste Wahl, SSRI hochdosiert möglich ärztlich."),
E("Körperdysmorphe Störung", G3, "F45.2 (Hypochondrische Störung, inkl. Dysmorphophobie)", "6B21", "Body Dysmorphic Disorder, F45.22",
  "Übermäßige Beschäftigung mit einem wahrgenommenen Makel im Aussehen, der für andere kaum oder nicht sichtbar ist, mit Kontroll-, Vergleichs- oder Verbergehandlungen.",
  ["Stundenlange Beschäftigung mit Haut, Nase, Haaren, Körperform", "Spiegelkontrollen oder Spiegelvermeidung", "Vergleichen, Rückversicherung, Verstecken (Make-up, Kleidung)", "Wiederholte kosmetische Eingriffe ohne Zufriedenheit", "Scham, Rückzug, Suizidrisiko erhöht"],
  "Wahrnehmungs- und Aufmerksamkeitsbias auf Details, frühe Hänseleien/Beschämung, Perfektionismus, soziokulturelle Schönheitsideale, Verbindung zu Zwangsspektrum.",
  "Der Blick bleibt an einem Detail hängen und wird durch Kontrollieren und Vergleichen immer fixierter.",
  "Ihr Leid ist echt, auch wenn andere den Makel nicht sehen. Hilfe liegt in der Veränderung des Blicks und Verhaltens, nicht in weiteren Eingriffen.",
  "KVT mit Spiegelexposition, Abbau von Kontroll- und Verbergeverhalten, kognitive Arbeit am Körperbild, ERP-Prinzipien.",
  "Zusammenhang mit Scham, Selbstwert und frühen Erfahrungen.",
  "Rolle von Aussehen im Familiensystem, Normen.",
  "Selbstakzeptanz, Körpererleben, Schamarbeit.",
  "Suizidrisiko ernst nehmen. Kosmetische Eingriffe meist nicht hilfreich."),
E("Krankheitsangststörung (Hypochondrie)", G3, "F45.2", "6B23", "Illness Anxiety Disorder, F45.21",
  "Anhaltende Angst oder Überzeugung, an einer schweren Krankheit zu leiden, trotz unauffälliger Befunde, mit Kontroll- oder Vermeidungsverhalten.",
  ["Ständige Gedanken an schwere Erkrankung", "Wiederholte Arztbesuche oder Vermeidung", "Körperabtasten, Internetrecherche", "Beruhigung hält nur kurz", "Fehlinterpretation harmloser Körpersignale"],
  "Katastrophisierende Bewertung körperlicher Empfindungen, selektive Aufmerksamkeit, Krankheitserfahrungen in Kindheit/Familie, Modelllernen.",
  "Normale Körperempfindungen werden als gefährlich gedeutet, was Angst und noch mehr Körperwahrnehmung erzeugt.",
  "Ihre Angst ist real, auch wenn die Befunde unauffällig sind. Der Weg führt über weniger Kontrollieren, nicht über mehr Untersuchungen.",
  "Psychoedukation, Verhaltensexperimente, Reaktionsmanagement (Rückversicherung, Checken, Googeln), kognitive Umstrukturierung.",
  "Bedeutung von Verletzlichkeit und Fürsorge, frühere Verlusterfahrungen.",
  "Rolle der Krankheitsangst im System, Fürsorgemuster.",
  "Gefühlsarbeit, Entlastung von Sorge.",
  "Ärztliche Basisabklärung, dann Konsequenz im Umgang mit Rückversicherung."),
]
